<script setup>
import { computed, onBeforeUnmount, onMounted, ref } from 'vue';
import { useHomepageStore } from '@/stores/homepage';
import FeaturedProducts from '@/components/guest/FeaturedProducts.vue';
import bannerApi from '@/api/banner';
import { productApi, storeApi } from '@/api';

const homepageStore = useHomepageStore();
const currentSlide = ref(0);
const carouselPaused = ref(false);
const reduceMotion = ref(false);
const categories = ref([]);
const invalidCategoryImages = ref(new Set());
const storeName = ref('FastGuy');
const storeAddress = ref('');
const mapEmbedUrl = computed(() => storeAddress.value ? `https://www.google.com/maps?q=${encodeURIComponent(storeAddress.value)}&output=embed` : '');
const mapOpenUrl = computed(() => storeAddress.value ? `https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(storeAddress.value)}` : '');
const fallbackImage = 'data:image/svg+xml,%3Csvg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1200 700"%3E%3Crect width="1200" height="700" fill="%231b1714"/%3E%3Ccircle cx="900" cy="350" r="250" fill="%23f26a2e" fill-opacity=".18"/%3E%3C/svg%3E';
const fallbackSlides = [
  { title: 'Món ngon cho mọi cuộc vui', subtitle: 'Chọn món bạn thích, đặt nhanh và tận hưởng một bữa ăn trọn vị.', cta: 'Chọn món ngay', link: '/menu', image: fallbackImage },
  { title: 'Bữa ngon không cần phải chờ', subtitle: 'Thực đơn rõ ràng, món dễ chọn và hành trình đơn hàng luôn trong tầm mắt.', cta: 'Khám phá thực đơn', link: '/menu', image: fallbackImage },
];
const banners = ref(fallbackSlides);
const activeSlide = computed(() => banners.value[currentSlide.value] || fallbackSlides[0]);
let slideInterval;
let motionQuery;

function listFrom(data) { return Array.isArray(data) ? data : data?.items || data?.content || data?.data || []; }
function hideCategoryImage(id) { invalidCategoryImages.value = new Set([...invalidCategoryImages.value, id]); }
function categoryIcon(name) {
  const value = String(name || '').toLocaleLowerCase('vi');
  if (value.includes('gà')) return 'bi-fire';
  if (value.includes('burger') || value.includes('bánh')) return 'bi-circle-square';
  if (value.includes('uống') || value.includes('nước')) return 'bi-cup-straw';
  if (value.includes('kèm') || value.includes('khoai')) return 'bi-box2-heart';
  return 'bi-grid';
}
function navigateSlide(index) { currentSlide.value = index; startCarousel(); }
function stopCarousel() { clearInterval(slideInterval); slideInterval = undefined; }
function startCarousel() { stopCarousel(); if (!reduceMotion.value && !carouselPaused.value && banners.value.length > 1) slideInterval = setInterval(() => { currentSlide.value = (currentSlide.value + 1) % banners.value.length; }, 5000); }
function setPaused(value) { carouselPaused.value = value; value ? stopCarousel() : startCarousel(); }
function updateMotion(event) { reduceMotion.value = event.matches; startCarousel(); }

onMounted(async () => {
  motionQuery = window.matchMedia('(prefers-reduced-motion: reduce)');
  reduceMotion.value = motionQuery.matches;
  motionQuery.addEventListener('change', updateMotion);
  homepageStore.load();
  const [bannerResult, categoryResult, storeResult] = await Promise.allSettled([bannerApi.getActive(), productApi.getCategories(), storeApi.getConfig()]);
  if (bannerResult.status === 'fulfilled') banners.value = bannerResult.value?.length ? bannerResult.value : fallbackSlides;
  if (categoryResult.status === 'fulfilled') categories.value = listFrom(categoryResult.value).map(item => ({ id: item.categoryId, name: item.name, imageUrl: item.imageUrl || '' })).filter(item => item.id && item.name).slice(0, 6);
  if (storeResult.status === 'fulfilled') {
    storeName.value = String(storeResult.value?.storeName || 'FastGuy').trim();
    storeAddress.value = String(storeResult.value?.storeAddress || '').trim();
  }
  currentSlide.value = 0;
  startCarousel();
});
onBeforeUnmount(() => { stopCarousel(); motionQuery?.removeEventListener('change', updateMotion); });
</script>

<template>
  <div class="home-page">
    <section class="hero" aria-roledescription="carousel" aria-label="Ưu đãi và món nổi bật FastGuy" @mouseenter="setPaused(true)" @mouseleave="setPaused(false)" @focusin="setPaused(true)" @focusout="setPaused(false)">
      <div class="hero-glow" aria-hidden="true"></div>
      <div class="container hero-shell">
        <div class="hero-copy">
          <p class="hero-eyebrow"><i class="bi bi-fire" aria-hidden="true"></i> Ưu đãi hôm nay</p>
          <h1>{{ activeSlide.title }}</h1>
          <p class="hero-desc">{{ activeSlide.subtitle }}</p>
          <div class="hero-actions">
            <router-link :to="activeSlide.link || '/menu'" class="hero-btn">{{ activeSlide.cta || 'Chọn món ngay' }} <i class="bi bi-arrow-up-right" aria-hidden="true"></i></router-link>
            <router-link to="/track-order" class="hero-secondary"><i class="bi bi-geo-alt" aria-hidden="true"></i> Theo dõi đơn</router-link>
          </div>
          <div v-if="banners.length > 1" class="hero-navigation">
            <span class="hero-counter"><strong>{{ String(currentSlide + 1).padStart(2, '0') }}</strong> / {{ String(banners.length).padStart(2, '0') }}</span>
            <div class="hero-dots" role="group" aria-label="Chọn banner">
              <button v-for="(_, index) in banners" :key="index" :class="{ active: currentSlide === index }" :aria-label="`Chọn banner ${index + 1}`" :aria-current="currentSlide === index ? 'true' : undefined" @click="navigateSlide(index)"></button>
            </div>
            <div class="hero-arrows"><button aria-label="Banner trước" @click="navigateSlide((currentSlide - 1 + banners.length) % banners.length)"><i class="bi bi-arrow-left" aria-hidden="true"></i></button><button aria-label="Banner tiếp theo" @click="navigateSlide((currentSlide + 1) % banners.length)"><i class="bi bi-arrow-right" aria-hidden="true"></i></button></div>
          </div>
        </div>
        <div class="hero-visual">
          <div class="hero-image-wrap"><img :key="currentSlide" :src="activeSlide.imageUrl || activeSlide.image" :alt="activeSlide.title" width="900" height="720"></div>
          <span class="hero-stamp" aria-hidden="true">FAST<br>GUY</span>
          <div class="hero-note"><i class="bi bi-lightning-charge-fill" aria-hidden="true"></i><span><strong>Đặt nhanh</strong>Chọn món rõ ràng</span></div>
        </div>
      </div>
    </section>

    <section v-if="categories.length" class="quick-categories" aria-labelledby="quick-category-title">
      <div class="container quick-category-shell">
        <div><p>Chọn nhanh</p><h2 id="quick-category-title">Bạn muốn ăn gì hôm nay?</h2></div>
        <nav class="category-list" aria-label="Danh mục món ăn">
          <router-link v-for="category in categories" :key="category.id" class="category-card" :to="{ path: '/menu', query: { category: category.id } }"><span class="category-image"><img v-if="category.imageUrl && !invalidCategoryImages.has(category.id)" :src="category.imageUrl" :alt="category.name" loading="lazy" @error="hideCategoryImage(category.id)"><span v-else class="category-image-fallback"><span class="category-icon"><i :class="`bi ${categoryIcon(category.name)}`" aria-hidden="true"></i></span></span></span><strong>{{ category.name }}</strong><span class="category-arrow"><i class="bi bi-arrow-up-right" aria-hidden="true"></i></span></router-link>
        </nav>
      </div>
    </section>

    <FeaturedProducts :products="homepageStore.bestSellers" :loading="homepageStore.loading" :error="homepageStore.error" @retry="homepageStore.retry" />

    <section class="story-section" aria-labelledby="home-story-title">
      <div class="container story-shell">
        <div class="story-copy"><p class="story-kicker">Một bữa ăn nhỏ, một ngày dài</p><h2 id="home-story-title"><span>Cuộc sống có thể vội.</span><span>Bữa ăn thì không.</span></h2><p>Giữa một buổi học kéo dài, một ca làm bận rộn hay một deadline đang đợi, bạn vẫn xứng đáng có một bữa ăn tử tế.</p><p>FastGuy giúp bạn chọn món rõ ràng, đặt nhanh và tiếp tục ngày dài mà không bỏ quên chính mình.</p><router-link to="/menu" class="story-cta">Chọn bữa ăn của bạn <i class="bi bi-arrow-right" aria-hidden="true"></i></router-link></div>
        <figure class="story-visual"><img src="https://res.cloudinary.com/ds4dnsj0o/image/upload/v1787055489/Image_Cloudinery/Home/fastguy-home-story_lfyhtg.jpg" alt="Người trẻ dùng bữa khi làm việc trên laptop" loading="lazy" width="1600" height="1067"><figcaption><span>FastGuy pause</span><strong>Một khoảng nghỉ vừa đủ để đi tiếp.</strong></figcaption></figure>
      </div>
    </section>
    <section class="experience-section" aria-labelledby="steps-title"><div class="container steps"><div class="steps-heading"><p>Đặt món thật dễ</p><h2 id="steps-title">Ba bước để có bữa ăn vừa ý</h2><span>Từ lúc chọn món đến khi nhận hàng, mọi bước đều rõ ràng.</span></div><div class="experience-grid"><router-link class="experience-card" to="/menu" aria-label="Chọn món trong thực đơn"><span>1</span><i class="bi bi-phone" aria-hidden="true"></i><div><h3>Chọn món</h3><p>Tìm món đúng khẩu vị trong thực đơn.</p></div><i class="bi bi-arrow-up-right card-arrow" aria-hidden="true"></i></router-link><router-link class="experience-card" to="/cart" aria-label="Kiểm tra giỏ hàng"><span>2</span><i class="bi bi-bag-check" aria-hidden="true"></i><div><h3>Kiểm tra giỏ</h3><p>Xem lại món, tùy chọn và tổng tiền.</p></div><i class="bi bi-arrow-up-right card-arrow" aria-hidden="true"></i></router-link><router-link class="experience-card" to="/track-order" aria-label="Theo dõi đơn hàng"><span>3</span><i class="bi bi-geo-alt" aria-hidden="true"></i><div><h3>Theo dõi đơn</h3><p>Theo dõi trạng thái xử lý và giao đơn.</p></div><i class="bi bi-arrow-up-right card-arrow" aria-hidden="true"></i></router-link></div></div></section>
    <section class="home-reasons" aria-labelledby="home-reasons-title"><div class="container"><div class="steps-heading"><p>Vì sao chọn FastGuy</p><h2 id="home-reasons-title">Một trải nghiệm đặt món dễ dàng</h2></div><ul><li><strong>Món rõ giá, dễ chọn</strong><span>Thông tin món và giá luôn hiển thị rõ ràng.</span></li><li><strong>Tùy chỉnh theo khẩu vị</strong><span>Chọn phiên bản và tùy chọn phù hợp với bạn.</span></li><li><strong>Theo dõi trạng thái xử lý và giao đơn</strong><span>Xem từng trạng thái từ lúc xác nhận đến khi giao xong.</span></li></ul></div></section>

    <section v-if="storeAddress" class="store-location" aria-labelledby="store-location-title"><div class="container location-shell"><div class="location-copy"><p>Tìm FastGuy</p><h2 id="store-location-title">Ghé cửa hàng<br>gần bạn</h2><div class="location-address"><i class="bi bi-geo-alt-fill" aria-hidden="true"></i><div><strong>{{ storeName }}</strong><span>{{ storeAddress }}</span></div></div><a :href="mapOpenUrl" target="_blank" rel="noopener noreferrer">Mở trong Google Maps <i class="bi bi-arrow-up-right" aria-hidden="true"></i></a></div><div class="location-map"><iframe :src="mapEmbedUrl" :title="`Bản đồ ${storeName}`" loading="lazy" referrerpolicy="no-referrer-when-downgrade" allowfullscreen></iframe></div></div></section>
    <section class="home-cta"><div class="container"><div class="cta-panel"><div><span>Đói rồi đúng không?</span><h2>Chọn món. Đặt nhanh.<br>Ăn ngon.</h2><p>Một bữa ăn vừa ý chỉ cách bạn vài lần chạm.</p></div><router-link to="/menu">Khám phá thực đơn <i class="bi bi-arrow-up-right" aria-hidden="true"></i></router-link><div class="cta-mark" aria-hidden="true">FG</div></div></div></section>
  </div>
</template>

